/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  const i = line.lastIndexOf(",");

  const x = line
    .slice(1, i - 1)
    .split(",")
    .map(Number);

  const k = parseInt(line.slice(i + 1));

  console.log(getResult(x, k));
});

function getResult(x, k) {
  const n = x.length;

  const midIdx = Math.floor(n / 2);
  // x数组的中位数
  const mid = [...x].sort((a, b) => a - b)[midIdx];

  // 初始化滑窗0~k-1, window为滑窗内部元素的表达式计算结果
  let window = x[0];
  for (let i = 1; i < k; i++) {
    window -= x[i];
  }

  // window和中位数的差距
  let minDiff = Math.abs(mid - window);
  // window滑窗起始索引
  let idx = 0;

  // 滑窗右移
  for (let i = 1; i <= n - k; i++) {
    // 右移一格后，新滑窗的表达式计算结果
    window += -x[i - 1] + 2 * x[i] - x[i + k - 1];

    // 新滑窗window值和中位数的差距
    const diff = Math.abs(mid - window);

    // 结果最接近于数组中位数的下标 i ，如果有多个 i 满足条件，请返回最大的 i
    if (diff <= minDiff) {
      minDiff = diff;
      idx = i;
    }
  }

  return idx;
}

