#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 1000

int getResult(const int x[], int n, int k);

int cmp(const void *a, const void *b) {
    return (*(int *) a) - (*(int *) b);
}

int main() {
    char s[100000];
    scanf("%s", s);

    char *p = strrchr(s, ',');
    *p = '\0';

    int nums[MAX_SIZE];
    int nums_size = 0;

    char *token = strtok(s + 1, ",");
    while (token != NULL) {
        nums[nums_size++] = atoi(token);
        token = strtok(NULL, ",");
    }

    int k = atoi(p + 1);

    printf("%d\n", getResult(nums, nums_size, k));

    return 0;
}

int getResult(const int x[], int n, int k) {
    int x_cp[n];
    for(int i=0; i<n; i++) x_cp[i] = x[i];

    // 这里排序的是x_cp数组，不能改变原数组x
    qsort(x_cp, n, sizeof(int), cmp);

    // x数组的中位数
    int mid = x_cp[n / 2];

    // 初始化滑窗0~k-1, window为滑窗内部元素的表达式计算结果
    int window = x[0];
    for (int i = 1; i < k; i++) {
        window -= x[i];
    }

    // window和中位数的差距
    int minDiff = abs(mid - window);

    // window滑窗起始索引
    int idx = 0;

    // 滑窗右移
    for (int i = 1; i <= n - k; i++) {
        // 右移一格后，新滑窗的表达式计算结果
        window += -x[i - 1] + 2 * x[i] - x[i + k - 1];

        // 新滑窗window值和中位数的差距
        int diff = abs(mid - window);

        // 结果最接近于数组中位数的下标 i ，如果有多个 i 满足条件，请返回最大的 i
        if (diff <= minDiff) {
            minDiff = diff;
            idx = i;
        }
    }

    return idx;
}
